1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Deliberately additive: `policyBase * 1.1` is not float-equivalent
51	// (100 * 1.1 === 110.00000000000001), and the final rounding-up turns that
52	// stray ulp into a whole extra gold piece. Do not "simplify".
53	const withFirstInsuranceSurcharge = (policyBase: number): number =>
54	  policyBase + policyBase * FIRST_INSURANCE_RATE;
55	
56	// The MHPCO rounds premiums in its own favour.
57	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
58	
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	const COMPONENT_TYPES = ["rune", "moonstone"];
62	
63	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
64	
65	const groupByType = (items: Item[]): Item[][] => {
66	  const groups = new Map<string, Item[]>();
67	  for (const item of items) {
68	    const group = groups.get(item.type) ?? [];
69	    group.push(item);
70	    groups.set(item.type, group);
71	  }
72	  return [...groups.values()];
73	};
74	
75	const formsComponentBlock = (group: Item[]): boolean =>
76	  group.length === COMPONENT_BLOCK_SIZE &&
77	  COMPONENT_TYPES.includes(group[0].type);
78	
79	const sumOfItemBasePremiums = (items: Item[]): number =>
80	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
81	
82	const groupBasePremium = (group: Item[]): number =>
83	  formsComponentBlock(group)
84	    ? COMPONENT_BLOCK_PREMIUM
85	    : sumOfItemBasePremiums(group);
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
89	
90	const quotePremium = (items: Item[]): number =>
91	  roundedInMHPCOsFavour(
92	    withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE,
93	  );
94	
95	const runStep = (step: Step): StepResult => {
96	  if (step.op === "quote") return { premium: quotePremium(step.items) };
97	  throw new Error(`unsupported step: ${step.op}`);
98	};
99	
100	export const runScenario = (scenario: Scenario): ScenarioResult => ({
101	  results: scenario.steps.map(runStep),
102	});
